    @log_input_and_output
    def collect_snapshot_via_telnet_connection(self, local_path, bts_type='GNB'):
        """
        Download snapshot.zip from device unit via telnet.

        :param local_path: Path where file will be saved.
        :type  local_path: str
        :param bts_type: type of BTS, ENB or GNB
        :type bts_type: str
        """
        credentials = get_ssh_connection_credentials(bts_type=bts_type)

